from matplotlib.patches import Rectangle
fig = plt.gcf(); fig.set_size_inches(7.0, 2.2)
ax = fig.add_axes([0, 0, 1, 1])
blue = (0.8, 0.88, 1.0); orange = (1.0, 0.8, 0.55)
def tower(x0, npairs, extra, extra_as_pair=False):
    for i in range(npairs):
        for y in (0.0, 0.9):
            ax.add_patch(Rectangle((x0 + i * 0.9, y), 0.8, 0.8, fc=blue, ec='black', lw=1.0))
    if extra:
        ax.add_patch(Rectangle((x0 + npairs * 0.9, 0.9), 0.8, 0.8, fc=orange, ec='orange', lw=1.4, hatch='..'))
    if extra_as_pair:
        for y in (0.0, 0.9):
            ax.add_patch(Rectangle((x0 + npairs * 0.9, y), 0.8, 0.8, fc=orange, ec='orange', lw=1.4, hatch='..'))
tower(0.0, 2, True); ax.text(1.3, -0.5, '5', ha='center', fontsize=13)
ax.text(3.2, 0.8, '+', ha='center', va='center', fontsize=16)
tower(3.8, 4, True); ax.text(6.0, -0.5, '9', ha='center', fontsize=13)
ax.text(8.7, 0.8, '=', ha='center', va='center', fontsize=16)
tower(9.3, 6, False, True); ax.text(12.4, -0.5, '14: 7 pairs', ha='center', fontsize=13)
ax.set_xlim(-0.2, 15.8); ax.set_ylim(-0.8, 2.0); ax.set_aspect('equal'); ax.axis('off')
